namespace fs = std::filesystem;

namespace {

struct Bbox {
    double x1{};
    double y1{};
    double x2{};
    double y2{};
};

struct Label {
    int numeric_id{};
    std::string filename;
    std::string status;
    Bbox bbox;
    int width{};
    int height{};
};

struct Sequence {
