            {"capture_e_3430_3469", 3430, 3469},
        };
        fs::create_directories(args.output);

        std::ofstream summary_csv(args.output / "sequence_summary.csv");
        summary_csv << "sequence,frames,visible_frames,iou_ge_0_5_ratio,iou_ge_0_3_ratio,"
                       "retention_ratio,first_failure_frame,max_continuous_drift_frames,"
                       "recovered_after_lost,avg_inference_ms,p95_inference_ms,fps\n";
