from __future__ import annotations

import asyncio
import json
import time
from contextlib import asynccontextmanager
from datetime import datetime, timezone
from io import BytesIO
from pathlib import Path
from uuid import uuid4

from fastapi import FastAPI, Request, WebSocket, WebSocketDisconnect
from fastapi.responses import FileResponse, JSONResponse
from fastapi.staticfiles import StaticFiles
from PIL import Image

from src.stream_capture import SegmentedCaptureStore
from src.stream_negative_capture import NegativeCaptureStore
from src.streaming import StreamInferenceEngine, TemporalStabilizer

PROJECT_ROOT = Path(__file__).resolve().parent
WEB_ROOT = PROJECT_ROOT / "web" / "stream"
OUTPUT_ROOT = PROJECT_ROOT / "output-stream" / "live"
NEGATIVE_CAPTURE_ROOT = PROJECT_ROOT / "datasets" / "stream_negatives"
CAMERA_DOMAIN_ROOT = PROJECT_ROOT / "datasets" / "camera_domain_v1"


class SessionLogger:
    def __init__(self) -> None:
        stamp = datetime.now(timezone.utc).strftime("%Y%m%dT%H%M%SZ")
        self.session_id = f"live_{stamp}_{uuid4().hex[:8]}"
        self.root = OUTPUT_ROOT / self.session_id
        self.root.mkdir(parents=True, exist_ok=False)
        self.path = self.root / "stream_predictions.jsonl"

    def append(self, row: dict[str, object]) -> None:
        with self.path.open("a", encoding="utf-8") as handle:
            handle.write(json.dumps(row, ensure_ascii=False) + "\n")


@asynccontextmanager
async def lifespan(app: FastAPI):
    engine = StreamInferenceEngine(PROJECT_ROOT, prefer_cuda=True)
    app.state.engine = engine
    app.state.negative_capture = NegativeCaptureStore(NEGATIVE_CAPTURE_ROOT)
    app.state.segmented_capture = SegmentedCaptureStore(CAMERA_DOMAIN_ROOT)
    try:
        yield
    finally:
        engine.close()


app = FastAPI(title="Medical Device Stream MVP", lifespan=lifespan)
app.mount("/assets", StaticFiles(directory=WEB_ROOT), name="assets")


def _decode_image(payload: bytes) -> Image.Image:
    if not payload:
        raise ValueError("empty image payload")
    with Image.open(BytesIO(payload)) as source:
        return source.copy()


def _metadata(message: dict[str, object]) -> tuple[int, int]:
    return (
        int(message.get("frame_id", 0)),
        int(message.get("source_timestamp_ms", round(time.time() * 1000))),
    )


@app.get("/")
async def index() -> FileResponse:
    return FileResponse(WEB_ROOT / "index.html")


@app.get("/health")
async def health() -> JSONResponse:
    engine: StreamInferenceEngine = app.state.engine
    return JSONResponse(
        {
            "ok": True,
            "service": "medical-device-stream-mvp",
            "execution_provider": engine.execution_provider,
            "models": engine.model_versions,
            "camera_input": "browser_getUserMedia",
            "negative_capture_session": app.state.negative_capture.session_id,
            "camera_domain_capture": app.state.segmented_capture.summary(),
        }
    )


@app.get("/v1/capture/session/status")
async def segmented_capture_status() -> JSONResponse:
    return JSONResponse({"ok": True, **app.state.segmented_capture.summary()})


@app.post("/v1/capture/session/start")
async def start_segmented_capture(request: Request) -> JSONResponse:
    try:
        body = await request.json()
        label = str(body.get("label", ""))
        session_id, ordinal, split = app.state.segmented_capture.start(label)
    except (RuntimeError, ValueError, json.JSONDecodeError) as exc:
        return JSONResponse({"ok": False, "error": str(exc)}, status_code=400)
    return JSONResponse(
        {
            "ok": True,
            "session_id": session_id,
            "session_ordinal": ordinal,
            "split": split,
            "label": label,
            "count": 0,
            "target_count": app.state.segmented_capture.frames_per_session,
        }
    )


@app.post("/v1/capture/session/frame")
async def save_segmented_capture_frame(request: Request) -> JSONResponse:
    payload = await request.body()
    source_timestamp_ms = int(
        request.headers.get("x-source-timestamp-ms", round(time.time() * 1000))
    )
    try:
        captured = app.state.segmented_capture.save(payload, source_timestamp_ms)
    except (RuntimeError, ValueError) as exc:
        return JSONResponse({"ok": False, "error": str(exc)}, status_code=400)
    return JSONResponse(
        {
            "ok": True,
            "session_id": captured.session_id,
            "session_ordinal": captured.session_ordinal,
            "split": captured.split,
            "label": captured.capture_label,
            "filename": captured.filename,
            "count": captured.count,
            "target_count": app.state.segmented_capture.frames_per_session,
            "complete": captured.complete,
            "width": captured.width,
            "height": captured.height,
            "sha256": captured.sha256,
        }
    )


@app.post("/v1/capture/session/stop")
async def stop_segmented_capture() -> JSONResponse:
    result = app.state.segmented_capture.stop()
    return JSONResponse(
        {"ok": True, **result, "summary": app.state.segmented_capture.summary()}
    )


# Legacy negative-capture endpoints remain available for old saved sessions.
@app.post("/v1/capture/negative/start")
async def start_negative_capture() -> JSONResponse:
