Json marker_json(const std::vector<medvision::MarkerDetectionResult>& markers,
                 const medvision::MarkerDeviceEstimate& estimate) {
    Json values = Json::array();
    for (const auto& marker : markers) {
        Json corners = Json::array();
        for (const auto& point : marker.corners) corners.push_back(Json::array({point.x, point.y}));
        values.push_back({{"marker_id", marker.marker_id}, {"corners", corners},
                          {"center", Json::array({marker.center.x, marker.center.y})},
                          {"side_length_px", marker.side_length_px}, {"rotation_deg", marker.rotation_deg},
                          {"confidence", marker.confidence}});
    }
    return {{"marker_detected", estimate.marker_detected}, {"visible_marker_ids", estimate.visible_marker_ids},
            {"markers", values}, {"single_marker_fallback", estimate.single_marker_fallback},
            {"source", estimate.source}, {"device_orientation", estimate.marker_detected ? Json(estimate.orientation_deg) : Json(nullptr)},
            {"detection_confidence", estimate.marker_detected ? Json(estimate.confidence) : Json(nullptr)}};
}

