namespace medvision {

struct MarkerDetector::Impl {
    apriltag_family_t* family{tag36h11_create()};
    apriltag_detector_t* detector{apriltag_detector_create()};
    mutable std::mutex mutex;

    Impl() {
        if (family == nullptr || detector == nullptr) throw std::runtime_error("cannot create AprilTag detector");
        apriltag_detector_add_family_bits(detector, family, 1);
        detector->nthreads = 1;
        detector->quad_decimate = 1.0F;
        detector->quad_sigma = 0.0F;
        detector->refine_edges = true;
        detector->decode_sharpening = 0.25;
    }

    ~Impl() {
        if (detector != nullptr) apriltag_detector_destroy(detector);
        if (family != nullptr) tag36h11_destroy(family);
    }
};

MarkerDetector::MarkerDetector() : impl_(new Impl()) {}
MarkerDetector::~MarkerDetector() { delete impl_; }

std::vector<MarkerDetectionResult> MarkerDetector::detect_jpeg(const std::vector<std::uint8_t>& jpeg) const {
    const cv::Mat encoded(1, static_cast<int>(jpeg.size()), CV_8UC1, const_cast<std::uint8_t*>(jpeg.data()));
    const cv::Mat bgr = cv::imdecode(encoded, cv::IMREAD_COLOR);
    if (bgr.empty()) throw std::invalid_argument("marker input is not a valid JPEG or PNG");
    return detect_bgr(bgr);
}

std::vector<MarkerDetectionResult> MarkerDetector::detect_bgr(const cv::Mat& bgr) const {
    if (bgr.empty()) throw std::invalid_argument("marker input image is empty");
    cv::Mat gray;
    cv::cvtColor(bgr, gray, cv::COLOR_BGR2GRAY);
    if (!gray.isContinuous()) gray = gray.clone();
    image_u8_t image{gray.cols, gray.rows, static_cast<int>(gray.step), gray.data};
    std::lock_guard<std::mutex> lock(impl_->mutex);
    zarray_t* detections = apriltag_detector_detect(impl_->detector, &image);
    std::vector<MarkerDetectionResult> output;
    const int count = zarray_size(detections);
    for (int index = 0; index < count; ++index) {
        apriltag_detection_t* detection{};
        zarray_get(detections, index, &detection);
        if (detection == nullptr || (detection->id != 21 && detection->id != 22)) continue;
        MarkerDetectionResult value;
        value.detected = true;
        value.marker_id = detection->id;
        value.center = {static_cast<float>(detection->c[0]), static_cast<float>(detection->c[1])};
        float perimeter{};
        for (int corner = 0; corner < 4; ++corner) {
            value.corners[corner] = {static_cast<float>(detection->p[corner][0]), static_cast<float>(detection->p[corner][1])};
            perimeter += cv::norm(value.corners[corner] - value.corners[(corner + 1) % 4]);
        }
        value.side_length_px = perimeter / 4.0F;
        const cv::Point2f edge = value.corners[1] - value.corners[0];
        value.rotation_deg = std::atan2(edge.y, edge.x) * 180.0F / static_cast<float>(CV_PI);
        const float hamming_factor = detection->hamming == 0 ? 1.0F : 0.6F;
        value.confidence = std::clamp((detection->decision_margin / 80.0F) * hamming_factor, 0.0F, 1.0F);
        output.push_back(value);
    }
    apriltag_detections_destroy(detections);
    std::sort(output.begin(), output.end(), [](const auto& left, const auto& right) { return left.marker_id < right.marker_id; });
    return output;
}

