cv::Mat make_tag(apriltag_family_t* family, int id, int size) {
    image_u8_t* raw = apriltag_to_image(family, static_cast<uint32_t>(id));
    if (raw == nullptr) throw std::runtime_error("cannot render AprilTag");
    cv::Mat source(raw->height, raw->width, CV_8UC1, raw->buf, raw->stride);
    cv::Mat padded;
    cv::copyMakeBorder(source, padded, raw->height, raw->height, raw->width, raw->width, cv::BORDER_CONSTANT, cv::Scalar(255));
    image_u8_destroy(raw);
    cv::resize(padded, padded, cv::Size(size, size), 0.0, 0.0, cv::INTER_NEAREST);
    return padded;
}

void put_centered(cv::Mat& page, const std::string& text, int y, double scale) {
    int baseline{}; const auto size = cv::getTextSize(text, cv::FONT_HERSHEY_SIMPLEX, scale, 2, &baseline);
    cv::putText(page, text, cv::Point((page.cols - size.width) / 2, y), cv::FONT_HERSHEY_SIMPLEX, scale, cv::Scalar(0), 2, cv::LINE_AA);
}

