#include "medvision/marker_geometry.hpp"

#include <algorithm>
#include <cmath>
#include <stdexcept>

#include <yaml-cpp/yaml.h>

namespace medvision {
namespace {

const MarkerDetectionResult* find_marker(const std::vector<MarkerDetectionResult>& markers, int marker_id) {
    const auto found = std::find_if(markers.begin(), markers.end(), [marker_id](const auto& marker) { return marker.marker_id == marker_id; });
    return found == markers.end() ? nullptr : &*found;
}

cv::Point2f unit_vector(const cv::Point2f& point) {
    const float length = std::sqrt(point.dot(point));
    if (length < 1.0e-5F) return {1.0F, 0.0F};
    return point * (1.0F / length);
}

std::optional<BBox> clipped_bbox(const cv::RotatedRect& rect, int width, int height) {
    cv::Point2f vertices[4]; rect.points(vertices);
    float x1 = vertices[0].x, y1 = vertices[0].y, x2 = vertices[0].x, y2 = vertices[0].y;
    for (const auto& point : vertices) { x1 = std::min(x1, point.x); y1 = std::min(y1, point.y); x2 = std::max(x2, point.x); y2 = std::max(y2, point.y); }
    BBox box{std::clamp(x1, 0.0F, static_cast<float>(width - 1)), std::clamp(y1, 0.0F, static_cast<float>(height - 1)),
             std::clamp(x2, 0.0F, static_cast<float>(width - 1)), std::clamp(y2, 0.0F, static_cast<float>(height - 1))};
    return (box.x2 > box.x1 && box.y2 > box.y1) ? std::optional<BBox>(box) : std::nullopt;
}

float degrees(const cv::Point2f& axis) { return std::atan2(axis.y, axis.x) * 180.0F / static_cast<float>(CV_PI); }

}  // namespace

MarkerDeviceGeometryConfig load_marker_geometry(const std::string& yaml_path) {
    const YAML::Node node = YAML::LoadFile(yaml_path);
    MarkerDeviceGeometryConfig value;
    value.head_marker_id = node["head_marker_id"].as<int>(value.head_marker_id);
    value.tail_marker_id = node["tail_marker_id"].as<int>(value.tail_marker_id);
    value.device_length_mm = node["device_length_mm"].as<float>(value.device_length_mm);
    value.device_width_mm = node["device_width_mm"].as<float>(value.device_width_mm);
    value.head_marker_to_tip_mm = node["head_marker_to_tip_mm"].as<float>(value.head_marker_to_tip_mm);
    value.tail_marker_to_end_mm = node["tail_marker_to_end_mm"].as<float>(value.tail_marker_to_end_mm);
    value.marker_size_mm = node["marker_size_mm"].as<float>(value.marker_size_mm);
    value.marker_axis_offset_deg = node["marker_axis_offset_deg"].as<float>(value.marker_axis_offset_deg);
    if (value.head_marker_id == value.tail_marker_id || value.marker_size_mm <= 0.0F || value.device_length_mm <= value.head_marker_to_tip_mm + value.tail_marker_to_end_mm) {
        throw std::invalid_argument("invalid marker geometry configuration");
    }
    return value;
}

MarkerDeviceEstimate estimate_device_from_markers(const std::vector<MarkerDetectionResult>& detections,
                                                   const MarkerDeviceGeometryConfig& config,
                                                   int image_width, int image_height) {
    MarkerDeviceEstimate result;
    const auto* head = find_marker(detections, config.head_marker_id);
    const auto* tail = find_marker(detections, config.tail_marker_id);
    for (const auto& marker : detections) result.visible_marker_ids.push_back(marker.marker_id);
    if (head == nullptr && tail == nullptr) return result;
    result.marker_detected = true;
    if (head != nullptr && tail != nullptr) {
        const cv::Point2f axis = unit_vector(head->center - tail->center);
        const float expected_gap_mm = config.device_length_mm - config.head_marker_to_tip_mm - config.tail_marker_to_end_mm;
        const float pixels_per_mm = cv::norm(head->center - tail->center) / expected_gap_mm;
        const cv::Point2f tip = head->center + axis * (config.head_marker_to_tip_mm * pixels_per_mm);
        const cv::Point2f end = tail->center - axis * (config.tail_marker_to_end_mm * pixels_per_mm);
        const cv::Point2f center = (tip + end) * 0.5F;
        result.orientation_deg = degrees(axis);
        result.oriented_box = cv::RotatedRect(center, cv::Size2f(cv::norm(tip - end), config.device_width_mm * pixels_per_mm), result.orientation_deg);
        result.bbox = clipped_bbox(*result.oriented_box, image_width, image_height);
        result.treatment_head_point = tip;
        result.confidence = std::min(head->confidence, tail->confidence);
        result.source = "dual_marker";
        return result;
    }
    const auto& marker = head != nullptr ? *head : *tail;
    const float angle = (marker.rotation_deg + config.marker_axis_offset_deg) * static_cast<float>(CV_PI) / 180.0F;
    cv::Point2f axis{std::cos(angle), std::sin(angle)};
    if (tail != nullptr) axis *= -1.0F;
    const float pixels_per_mm = marker.side_length_px / config.marker_size_mm;
    const cv::Point2f tip = head != nullptr ? marker.center + axis * (config.head_marker_to_tip_mm * pixels_per_mm)
                                             : marker.center - axis * ((config.device_length_mm - config.tail_marker_to_end_mm) * pixels_per_mm);
    const cv::Point2f end = head != nullptr ? marker.center - axis * ((config.device_length_mm - config.head_marker_to_tip_mm) * pixels_per_mm)
                                             : marker.center - axis * (config.tail_marker_to_end_mm * pixels_per_mm);
    result.orientation_deg = degrees(axis);
    result.oriented_box = cv::RotatedRect((tip + end) * 0.5F, cv::Size2f(cv::norm(tip - end), config.device_width_mm * pixels_per_mm), result.orientation_deg);
    result.bbox = clipped_bbox(*result.oriented_box, image_width, image_height);
    result.treatment_head_point = tip;
    result.confidence = marker.confidence * 0.65F;
    result.single_marker_fallback = true;
    result.source = head != nullptr ? "head_marker_fallback" : "tail_marker_fallback";
    return result;
}

