namespace medvision {

struct MarkerDeviceGeometryConfig {
    int head_marker_id{21};
    int tail_marker_id{22};
    float device_length_mm{180.0F};
    float device_width_mm{45.0F};
    float head_marker_to_tip_mm{28.0F};
    float tail_marker_to_end_mm{22.0F};
    float marker_size_mm{60.0F};
    float marker_axis_offset_deg{-90.0F};
};

struct MarkerDeviceEstimate {
    bool marker_detected{};
    std::vector<int> visible_marker_ids;
    std::optional<BBox> bbox;
    std::optional<cv::RotatedRect> oriented_box;
    std::optional<cv::Point2f> treatment_head_point;
    float orientation_deg{};
