const content=`"use strict";

const TARGET_AI_FPS = 10;
const AI_INTERVAL_MS = 1000 / TARGET_AI_FPS;
const JPEG_QUALITY = 0.70;
const INTERPOLATION_DELAY_MS = 80;
const MAX_EXTRAPOLATION_MS = 80;
const MAX_OVERLAY_AGE_MS = 250;

const video = document.querySelector("#video");
const canvas = document.querySelector("#view");
const ctx = canvas.getContext("2d");
const capture = document.createElement("canvas");
const captureCtx = capture.getContext("2d");
const seed = document.createElement("canvas");
const seedCtx = seed.getContext("2d");
const stage = document.querySelector("#stage");
const startBtn = document.querySelector("#start");
const freezeBtn = document.querySelector("#freeze");
const confirmBtn = document.querySelector("#confirm");
const cancelBtn = document.querySelector("#cancel");
const resetBtn = document.querySelector("#reset");
const stopBtn = document.querySelector("#stop");
const statusEl = document.querySelector("#status");
const backgroundBtn = document.querySelector("#background-toggle");
const manualModeBtn = document.querySelector("#manual-mode");
const markerModeBtn = document.querySelector("#marker-mode");

let media = null;
let requestTimer = null;
let renderHandle = null;
let videoFrameHandle = null;
let inFlight = false;
let frameId = 0;
let latest = null;
let latestReceivedAt = 0;
let frozen = false;
let dragStart = null;
let draftBox = null;
let manualEnabled = false;
let markerEnabled = false;
let whitenBackground = true;
let boxSamples = [];
let pointSamples = [];
let rateWindowStartedAt = performance.now();
let aiResponses = 0;
let cameraFrames = 0;
let renderFrames = 0;
let skippedFrames = 0;

function status(text, warn = false) {
  statusEl.textContent = text;
  statusEl.style.borderLeftColor = warn ? "#ffd64a" : "#17775a";
}

function setBadge(selector, label, enabled) {
  const element = document.querySelector(selector);
  element.textContent = label + "：" + (enabled ? "开启" : "关闭");
  element.className = "badge " + (enabled ? "on" : "off");
}

function configurePageCopy() {
  document.title = "医美设备手动画框流畅跟踪";
  document.querySelector("h1").textContent = "医美设备手动画框流畅跟踪";
  document.querySelector(".lead").textContent =
    "当前默认使用一次手动画框初始化 SAM2。摄像头原画按约 30 FPS 连续显示，AI 约 8–12 FPS 更新，设备框通过安全平滑连续绘制。";
  document.querySelector(".notice").innerHTML =
    "<strong>当前模式：</strong>手动画框开启，AprilTag 默认关闭。启动摄像头后冻结画面，框选一次设备即可开始跟踪。完整丢失后请重新框选。";
  document.querySelector(".legend").innerHTML =
    '<span><i class="dot" style="background:#f58b23"></i>橙色：自动诊断候选框</span>' +
    '<span><i class="dot" style="background:#ed3343"></i>红色：平滑设备框</span>' +
    '<span><i class="dot" style="background:#f34ca8"></i>粉色：接触点</span>' +
    '<span><i class="dot" style="background:#ffd64a"></i>黄色：不确定或需要复查</span>';
  document.querySelector(".steps").innerHTML =
    '<div class="step"><strong>1. 启动摄像头</strong>原画会按摄像头原生约 30 FPS 连续显示。</div>' +
    '<div class="step"><strong>2. 冻结并框选</strong>点击“冻结并手动画框”，拖动矩形包住设备，再确认开始跟踪。</div>' +
    '<div class="step"><strong>3. 观察与重选</strong>红框会平滑跟随；设备完全丢失或移出画面后，清除状态并重新框选。</div>';
  startBtn.textContent = "启动摄像头";
  freezeBtn.textContent = "冻结并手动画框";
  confirmBtn.textContent = "使用此框开始流畅跟踪";
  resetBtn.textContent = "清除状态并重新框选";
  stopBtn.textContent = "停止摄像头";

  const grid = document.querySelector(".grid");
  const additions = [
    ["camera-fps", "摄像头帧率"],
    ["render-fps", "画面渲染帧率"],
    ["skipped-frames", "跳过的旧帧"],
  ];
  for (const [id, label] of additions.reverse()) {
    if (document.querySelector("#" + id)) continue;
    const metric = document.createElement("div");
    metric.className = "metric";
    metric.innerHTML = "<small>" + label + "</small><span id=\\"" + id + "\\">0</span>";
    grid.prepend(metric);
  }
  const fpsLabel = document.querySelector("#fps").previousElementSibling;
  if (fpsLabel) fpsLabel.textContent = "AI 有效推理帧率";
}

function applyModes(modes) {
  manualEnabled = Boolean(modes.enable_manual_bbox_assist);
  markerEnabled = Boolean(modes.enable_marker_assist);
  setBadge("#manual-mode", "手动画框", manualEnabled);
  setBadge("#marker-mode", "AprilTag", markerEnabled);
  document.querySelectorAll(".manual-control").forEach((element) => {
    element.classList.toggle("hidden", !manualEnabled);
  });
  freezeBtn.disabled = !media || !manualEnabled;
  if (!manualEnabled && frozen) cancelSelection();
}

async function updateModes(nextManual, nextMarker) {
  manualModeBtn.disabled = true;
  markerModeBtn.disabled = true;
  try {
    const response = await fetch("/v1/assist/modes", {
      method: "POST",
      headers: {"Content-Type": "application/json"},
      body: JSON.stringify({
        enable_manual_bbox_assist: nextManual,
        enable_marker_assist: nextMarker,
      }),
    });
    const data = await response.json();
    if (!data.ok) throw new Error(data.error);
    applyModes(data.assist_modes);
    status(
      "辅助模式已更新：手动画框" + (manualEnabled ? "开启" : "关闭") +
      "，AprilTag" + (markerEnabled ? "开启" : "关闭") + "。"
    );
  } catch (error) {
    status("辅助模式更新失败：" + error.message, true);
  } finally {
    manualModeBtn.disabled = false;
    markerModeBtn.disabled = false;
  }
}

function fit() {
  if (!video.videoWidth) return;
  for (const target of [canvas, capture, seed]) {
    if (target.width !== video.videoWidth || target.height !== video.videoHeight) {
      target.width = video.videoWidth;
      target.height = video.videoHeight;
    }
  }
}

function validBox(box) {
  return Array.isArray(box) && box.length === 4 &&
    box.every(Number.isFinite) && box[2] > box[0] && box[3] > box[1];
}

function validPoint(point) {
  return Array.isArray(point) && point.length === 2 && point.every(Number.isFinite);
}

function rememberResult(result, receivedAt) {
  latest = result;
  latestReceivedAt = receivedAt;
  if (result.state === "TRACKING" && validBox(result.device_bbox)) {
    boxSamples.push({time: receivedAt, value: result.device_bbox.map(Number)});
    boxSamples = boxSamples.slice(-2);
    if (
      validPoint(result.contact_point) &&
      result.contact_visibility !== "not_annotatable" &&
      (result.contact_updated !== false || pointSamples.length === 0)
    ) {
      pointSamples.push({time: receivedAt, value: result.contact_point.map(Number)});
      pointSamples = pointSamples.slice(-2);
    }
  } else if (result.state === "LOST" || result.state === "SEARCHING") {
    boxSamples = [];
    pointSamples = [];
  } else if (result.state === "UNCERTAIN") {
    pointSamples = [];
  }
}

function interpolateSamples(samples, now, kind) {
  if (!samples.length) return null;
  const current = samples[samples.length - 1];
  if (now - current.time > MAX_OVERLAY_AGE_MS) return null;
  if (samples.length === 1 || latest?.state !== "TRACKING") {
    return current.value.slice();
  }

  const previous = samples[samples.length - 2];
  const targetTime = now - INTERPOLATION_DELAY_MS;
  const duration = Math.max(current.time - previous.time, 1);
  if (targetTime <= current.time) {
    const alpha = Math.max(0, Math.min(1, (targetTime - previous.time) / duration));
    return current.value.map((value, index) =>
      previous.value[index] + (value - previous.value[index]) * alpha
    );
  }

  const extra = Math.min(targetTime - current.time, MAX_EXTRAPOLATION_MS);
  const factor = extra / duration;
  const limit = kind === "box"
    ? Math.max(current.value[2] - current.value[0], current.value[3] - current.value[1]) * 0.15
    : Math.min(canvas.width, canvas.height) * 0.025;
  return current.value.map((value, index) => {
    const movement = (value - previous.value[index]) * factor;
    return value + Math.max(-limit, Math.min(limit, movement));
  });
}

function drawBox(box, color, label, width = 6, dashed = false) {
  if (!validBox(box)) return;
  const [x1, y1, x2, y2] = box;
  ctx.save();
  ctx.strokeStyle = color;
  ctx.lineWidth = width;
  ctx.setLineDash(dashed ? [14, 8] : []);
  ctx.strokeRect(x1, y1, x2 - x1, y2 - y1);
  ctx.setLineDash([]);
  ctx.fillStyle = color;
  ctx.font = "bold 20px sans-serif";
  ctx.fillText(label, x1 + 6, Math.max(24, y1 + 24));
  ctx.restore();
}

function drawPoint(point) {
  if (!validPoint(point)) return;
  const [x, y] = point;
  const radius = Math.max(12, Math.min(canvas.width, canvas.height) * 0.017);
  ctx.save();
  ctx.strokeStyle = "#f34ca8";
  ctx.lineWidth = 6;
  ctx.beginPath();
  ctx.arc(x, y, radius, 0, Math.PI * 2);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(x - radius - 7, y);
  ctx.lineTo(x + radius + 7, y);
  ctx.moveTo(x, y - radius - 7);
  ctx.lineTo(x, y + radius + 7);
  ctx.stroke();
  ctx.restore();
}

function drawMarkers(markers) {
  for (const marker of markers || []) {
    const points = marker.corners || [];
    if (points.length !== 4) continue;
    ctx.save();
    ctx.strokeStyle = "#18a56f";
    ctx.fillStyle = "#18a56f";
    ctx.lineWidth = 5;
    ctx.beginPath();
    ctx.moveTo(points[0][0], points[0][1]);
    for (let index = 1; index < 4; index += 1) {
      ctx.lineTo(points[index][0], points[index][1]);
    }
    ctx.closePath();
    ctx.stroke();
    ctx.font = "bold 22px sans-serif";
    ctx.fillText("Tag " + marker.marker_id, points[0][0] + 5, Math.max(24, points[0][1] - 8));
    ctx.restore();
  }
}

function drawLiveFrame() {
  const polygon = latest && Array.isArray(latest.foreground_polygon)
    ? latest.foreground_polygon
    : [];
  if (!whitenBackground || polygon.length < 3) {
    ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
    return;
  }
  ctx.save();
  ctx.fillStyle = "#fff";
  ctx.fillRect(0, 0, canvas.width, canvas.height);
  ctx.beginPath();
  ctx.moveTo(polygon[0][0], polygon[0][1]);
  for (let index = 1; index < polygon.length; index += 1) {
    ctx.lineTo(polygon[index][0], polygon[index][1]);
  }
  ctx.closePath();
  ctx.clip();
  ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
  ctx.restore();
}

function paint(now) {
  renderFrames += 1;
  if (canvas.width) {
    if (frozen) {
      ctx.drawImage(seed, 0, 0);
    } else if (video.videoWidth) {
      drawLiveFrame();
    }

    if (!frozen && latest) {
      drawMarkers(latest.marker_corners);
      drawBox(latest.diagnostic_bbox, "#f58b23", "自动候选", 4);

      const smoothBox = interpolateSamples(boxSamples, now, "box");
      if (latest.state === "TRACKING") {
        drawBox(smoothBox, "#ed3343", "TRACKING");
        drawPoint(interpolateSamples(pointSamples, now, "point"));
      } else if (latest.state === "UNCERTAIN") {
        drawBox(smoothBox, "#ffd64a", "UNCERTAIN", 5, true);
      } else if (latest.state === "CANDIDATE") {
        drawBox(latest.device_bbox, "#f58b23", "CANDIDATE", 4);
      }

      if (
        latest.needs_review &&
        latest.state !== "SEARCHING" &&
        now - latestReceivedAt <= MAX_OVERLAY_AGE_MS
      ) {
        ctx.fillStyle = "#ffd64a";
        ctx.font = "bold 22px sans-serif";
        ctx.fillText("需复查：" + (latest.review_reasons || []).join(", "), 14, 32);
      }
    }

    if (draftBox) {
      drawBox(draftBox, "#ffd64a", "当前手动画框", 5, true);
    }
  }

  updateRateMetrics(now);
  renderHandle = requestAnimationFrame(paint);
}

function updateRateMetrics(now) {
  const elapsed = now - rateWindowStartedAt;
  if (elapsed < 1000) return;
  const scale = 1000 / elapsed;
  document.querySelector("#camera-fps").textContent =
    (cameraFrames * scale).toFixed(1) + " FPS";
  document.querySelector("#render-fps").textContent =
    (renderFrames * scale).toFixed(1) + " FPS";
  document.querySelector("#fps").textContent =
    (aiResponses * scale).toFixed(1) + " FPS";
  document.querySelector("#skipped-frames").textContent = String(skippedFrames);
  cameraFrames = 0;
  renderFrames = 0;
  aiResponses = 0;
  rateWindowStartedAt = now;
}

function observeVideoFrames() {
  if (!media || !video.requestVideoFrameCallback) return;
  videoFrameHandle = video.requestVideoFrameCallback(() => {
    cameraFrames += 1;
    observeVideoFrames();
  });
}

function canvasPoint(event) {
  const rect = canvas.getBoundingClientRect();
  return [
    (event.clientX - rect.left) * canvas.width / rect.width,
    (event.clientY - rect.top) * canvas.height / rect.height,
  ];
}

canvas.addEventListener("pointerdown", (event) => {
  if (!frozen || !manualEnabled) return;
  canvas.setPointerCapture(event.pointerId);
  dragStart = canvasPoint(event);
  draftBox = [dragStart[0], dragStart[1], dragStart[0], dragStart[1]];
});

canvas.addEventListener("pointermove", (event) => {
  if (!dragStart || !frozen) return;
  const point = canvasPoint(event);
  draftBox = [
    Math.min(dragStart[0], point[0]),
    Math.min(dragStart[1], point[1]),
    Math.max(dragStart[0], point[0]),
    Math.max(dragStart[1], point[1]),
  ];
  confirmBtn.disabled =
    draftBox[2] - draftBox[0] < 8 || draftBox[3] - draftBox[1] < 8;
});

canvas.addEventListener("pointerup", (event) => {
  if (canvas.hasPointerCapture(event.pointerId)) {
    canvas.releasePointerCapture(event.pointerId);
  }
  dragStart = null;
});

canvas.addEventListener("pointercancel", (event) => {
  if (canvas.hasPointerCapture(event.pointerId)) {
    canvas.releasePointerCapture(event.pointerId);
  }
  dragStart = null;
});

function toBlob(target, quality = JPEG_QUALITY) {
  return new Promise((resolve, reject) => {
    target.toBlob((blob) => {
      if (blob) resolve(blob);
      else reject(new Error("摄像头帧编码失败"));
    }, "image/jpeg", quality);
  });
}

function liveStatus() {
  if (latest?.state === "TRACKING") {
    return "设备跟踪中：原画连续显示，AI 结果正在安全平滑。";
  }
  if (latest?.state === "UNCERTAIN") {
    return "当前跟踪不确定，接触点已暂停；完全丢失后请重新框选。";
  }
  if (latest?.state === "CANDIDATE") {
    return "正在确认自动候选；也可以直接冻结画面并手动画框。";
  }
  return manualEnabled
    ? "请冻结当前画面并手动画框，或等待自动搜索结果。"
    : "系统正在自动搜索设备。";
}

async function sendFrame() {
  if (!media || frozen || !video.videoWidth) return;
  if (inFlight) {
    skippedFrames += 1;
    return;
  }

  inFlight = true;
  captureCtx.drawImage(video, 0, 0, capture.width, capture.height);
  const id = frameId;
  frameId += 1;
  const sentAt = performance.now();

  try {
    const body = await toBlob(capture, JPEG_QUALITY);
    const response = await fetch("/v1/stream/frame", {
      method: "POST",
      headers: {
        "Content-Type": "image/jpeg",
        "x-frame-id": String(id),
        "x-capture-timestamp-ms": String(Date.now()),
      },
      body,
    });
    const data = await response.json();
    if (!data.ok) throw new Error(data.error);
    const receivedAt = performance.now();
    rememberResult(data.result, receivedAt);
    aiResponses += 1;
    updateResultMetrics(sentAt, receivedAt);
    status(liveStatus(), latest.needs_review && latest.state !== "SEARCHING");
  } catch (error) {
    status("推理请求失败：" + error.message, true);
  } finally {
    inFlight = false;
  }
}

async function runAiLoop() {
  if (!media) return;
  const cycleStartedAt = performance.now();
  if (frozen) {
    requestTimer = setTimeout(runAiLoop, 40);
    return;
  }
  await sendFrame();
  const cycleMs = performance.now() - cycleStartedAt;
  requestTimer = setTimeout(runAiLoop, Math.max(0, AI_INTERVAL_MS - cycleMs));
}

function updateResultMetrics(sentAt, receivedAt) {
  document.querySelector("#state").textContent = latest.state || latest.track_state;
  document.querySelector("#source").textContent = latest.assist_source || "-";
  document.querySelector("#marker-ids").textContent =
    (latest.visible_marker_ids || []).join(", ") || "无";
  document.querySelector("#marker-source").textContent = latest.marker_source || "none";
  document.querySelector("#marker-score").textContent =
    Number(latest.marker_confidence || 0).toFixed(3);
  document.querySelector("#device-score").textContent =
    Number(latest.device_score || latest.detector_score || 0).toFixed(3);
  document.querySelector("#contact-state").textContent =
    latest.contact_visibility || "not_annotatable";
  document.querySelector("#latency").textContent =
    Number(latest.timings_ms?.total || 0).toFixed(1) + " / " +
    (receivedAt - sentAt).toFixed(1) + " ms";
}

